// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        // Assume valid parameters: non-empty _tos and v not causing overflow in token (simplified)
        vm.assume(_tos.length > 0);

        // Call transfer
        (bool success, bytes memory ret) = address(c).call(
            abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v)
        );

        // The rule: if transfer returns true, then the return value is true.
        // For the reference C, assert that when call succeeds, decoded boolean is true.
        if (success) {
            bool returnValue = abi.decode(ret, (bool));
            assertTrue(returnValue);
        }
    }
}

